            while (((ia < a.len) and (std.ascii.isWhitespace(a[@as(usize, @intCast(ia))]) or (a[@as(usize, @intCast(ia))] == 59)))) {
                ia = (ia + 1);
            }
            while (((ib < b.len) and (std.ascii.isWhitespace(b[@as(usize, @intCast(ib))]) or (b[@as(usize, @intCast(ib))] == 59)))) {
                ib = (ib + 1);
            }
            if (((ia == a.len) or (ib == b.len))) {
                return ((ia == a.len) and (ib == b.len));
            }
            const ca = (if ((a[@as(usize, @intCast(ia))] == 39)) 34 else a[@as(usize, @intCast(ia))]);
            const cb = (if ((b[@as(usize, @intCast(ib))] == 39)) 34 else b[@as(usize, @intCast(ib))]);
            if ((ca != cb)) {
                return false;
            }
            ia = (ia + 1);
            ib = (ib + 1);
        }
}

pub fn countLinesForDiff(t: []const u8) usize {
        if ((t.len == 0)) {
            return 0;
        }
        return (std.mem.count(u8, t, "\n") + @intFromBool((t[@as(usize, @intCast((t.len - 1)))] != 10)));
}

pub fn changedLines(allocator: std.mem.Allocator, a: []const u8, b: []const u8) ![2][]bool {
        const ca = try allocator.alloc(bool, countLinesForDiff(a));
        const cb = try allocator.alloc(bool, countLinesForDiff(b));
        _ = @memset(ca, false);
        _ = @memset(cb, false);
        var hunks = text_diff.diffLines(allocator, a, b);
        _ = &hunks;
        defer {
        _ = hunks.deinit(allocator);
        }
        var la: usize = 0;
        _ = &la;
        var lb: usize = 0;
        _ = &lb;
        var oa: usize = 0;
        _ = &oa;
        var ob: usize = 0;
        _ = &ob;
        for (hunks.items) |h| {
            _ = &h;
            la = (la + countLinesForDiff(a[oa..h.a_lo]));
            lb = (lb + countLinesForDiff(b[ob..h.b_lo]));
            const da = countLinesForDiff(a[h.a_lo..h.a_hi]);
            const db = countLinesForDiff(b[h.b_lo..h.b_hi]);
            if (((la + da) <= ca.len)) {
                _ = @memset(ca[la..(la + da)], true);
            }
            if (((lb + db) <= cb.len)) {
                _ = @memset(cb[lb..(lb + db)], true);
            }
            la = (la + da);
            lb = (lb + db);
            oa = h.a_hi;
            ob = h.b_hi;
        }
        return .{ ca, cb };
}

pub fn isIdentByte(b: u8) bool {
        return (((std.ascii.isAlphanumeric(b) or (b == 95)) or (b == 36)) or ((b & 128) != 0));
}

pub fn widen(text: []const u8, range: [2]usize) [2]usize {
        var lo = range[0];
        _ = &lo;
        var hi = range[1];
        _ = &hi;
        while (((((lo > 0) and isIdentByte(text[@as(usize, @intCast((lo - 1)))])) and (lo < text.len)) and isIdentByte(text[@as(usize, @intCast(lo))]))) {
            lo = (lo - 1);
        }
        while (((((hi < text.len) and isIdentByte(text[@as(usize, @intCast(hi))])) and (hi > 0)) and isIdentByte(text[@as(usize, @intCast((hi - 1)))]))) {
            hi = (hi + 1);
        }
        return .{ lo, hi };
}

pub fn diffSpan(a: []const u8, b: []const u8) [2]usize {
        const min_len = @min(a.len, b.len);
        var lo: usize = 0;
        _ = &lo;
        while (((lo < min_len) and (a[@as(usize, @intCast(lo))] == b[@as(usize, @intCast(lo))]))) {
            lo = (lo + 1);
        }
        const max_suffix = (min_len - lo);
        var suffix: usize = 0;
        _ = &suffix;
        while (((suffix < max_suffix) and (a[@as(usize, @intCast(((a.len - 1) - suffix)))] == b[@as(usize, @intCast(((b.len - 1) - suffix)))]))) {
            suffix = (suffix + 1);
        }
        return .{ lo, (a.len - suffix) };
}

pub fn sideOk(side: *const Side, line0: usize, text: []const u8, others: []const []const u8) bool {
        if (side.noImage(line0)) {
            if (trivial(text)) {
                return true;
            }
            for (cp_iter_slice(others)) |o| {
                _ = &o;
                if (looseEql(text, o)) {
                    return true;
                }
            }
            return false;
        }
        return side.keyedEqual(line0);
}

pub fn codeOnly(a: Op, aside: *const Side, al: usize, b: Op, bside: *const Side, bl: usize) bool {
        const ar = widen(a.text, diffSpan(a.text, b.text));
        const br = widen(b.text, diffSpan(b.text, a.text));
        const a_ok = (trivial(a.text[ar[0]..ar[1]]) or aside.mappedWithin(al, ar[0], ar[1]));
        const b_ok = (trivial(b.text[br[0]..br[1]]) or bside.mappedWithin(bl, br[0], br[1]));
        return (a_ok and b_ok);
}

pub fn project(allocator: std.mem.Allocator, old: []const u8, new: []const u8, key_old: *const Normalized, key_new: *const Normalized) !Projection {
        const kc = try changedLines(allocator, key_old.text, key_new.text);
        const so = try Side.init(allocator, old, key_old, kc[0]);
        const sn = try Side.init(allocator, new, key_new, kc[1]);
        const raw = try lineOps(allocator, old, new);
        var ops: std.ArrayListUnmanaged(Op) = .{};
        _ = &ops;
        var hidden: usize = 0;
        _ = &hidden;
        var i: usize = 0;
        _ = &i;
        var unseen_old: std.ArrayListUnmanaged([]const u8) = .{};
        _ = &unseen_old;
        var unseen_new: std.ArrayListUnmanaged([]const u8) = .{};
        _ = &unseen_new;
        var dels: std.ArrayListUnmanaged(Op) = .{};
        _ = &dels;
        var ins: std.ArrayListUnmanaged(Op) = .{};
        _ = &ins;
        var keep_d: std.ArrayListUnmanaged(Op) = .{};
        _ = &keep_d;
        var keep_n: std.ArrayListUnmanaged(Op) = .{};
        _ = &keep_n;
        while ((i < raw.len)) {
            if ((raw[@as(usize, @intCast(i))].kind == .equal)) {
                var op = raw[@as(usize, @intCast(i))];
                _ = &op;
                op.affected = ((!trivial(op.text)) and (so.noImage((op.old_no - 1)) != sn.noImage((op.new_no - 1))));
                _ = try ops.append(allocator, op);
                i = (i + 1);
                continue;
            }
            const start = i;
            while (((i < raw.len) and (raw[@as(usize, @intCast(i))].kind != .equal))) {
                i = (i + 1);
            }
            _ = dels.clearRetainingCapacity();
            _ = ins.clearRetainingCapacity();
            _ = unseen_old.clearRetainingCapacity();
            _ = unseen_new.clearRetainingCapacity();
            for (cp_iter_slice(raw[start..i])) |op| {
                _ = &op;
                if ((op.kind == .delete)) {
                    _ = try dels.append(allocator, op);
                    if ((so.noImage((op.old_no - 1)) and (!trivial(op.text)))) {
                        _ = try unseen_old.append(allocator, op.text);
                    }
                } else {
                    _ = try ins.append(allocator, op);
                    if ((sn.noImage((op.new_no - 1)) and (!trivial(op.text)))) {
                        _ = try unseen_new.append(allocator, op.text);
                    }
                }
            }
            if ((dels.items.len == ins.items.len)) {
                _ = keep_d.clearRetainingCapacity();
                _ = keep_n.clearRetainingCapacity();
                var k: usize = 0;
                _ = &k;
                while ((k < dels.items.len)) : (k = (k + 1)) {
                    const d = dels.items[@as(usize, @intCast(k))];
                    const n = ins.items[@as(usize, @intCast(k))];
                    const dl = (d.old_no - 1);
                    const nl = (n.new_no - 1);
                    var hide = (sideOk((&so), dl, d.text, unseen_new.items) and sideOk((&sn), nl, n.text, unseen_old.items));
                    _ = &hide;
                    if (((hide and (!so.noImage(dl))) and (!sn.noImage(nl)))) {
                        hide = codeOnly(d, (&so), dl, n, (&sn), nl);
                    }
                    if (hide) {
                        if ((!trivial(d.text))) {
                            hidden = (hidden + 1);
                        }
                        _ = try ops.appendSlice(allocator, keep_d.items);
                        _ = try ops.appendSlice(allocator, keep_n.items);
                        _ = keep_d.clearRetainingCapacity();
                        _ = keep_n.clearRetainingCapacity();
                        _ = try ops.append(allocator, Op{ .kind = .equal, .old_no = n.old_no, .new_no = n.new_no, .text = n.text, .affected = n.affected });
                    } else {
                        _ = try keep_d.append(allocator, d);
                        _ = try keep_n.append(allocator, n);
                    }
                }
                _ = try ops.appendSlice(allocator, keep_d.items);
                _ = try ops.appendSlice(allocator, keep_n.items);
            } else {
                for (dels.items) |d| {
                    _ = &d;
                    const dl = (d.old_no - 1);
                    var fold = sideOk((&so), dl, d.text, unseen_new.items);
                    _ = &fold;
                    if (((fold and (!so.noImage(dl))) and (ins.items.len > 0))) {
                        var matched = false;
                        _ = &matched;
                        for (ins.items) |n| {
                            _ = &n;
                            if (((!sn.noImage((n.new_no - 1))) and codeOnly(d, (&so), dl, n, (&sn), (n.new_no - 1)))) {
                                matched = true;
                                break;
                            }
                        }
                        fold = matched;
                    }
                    if (fold) {
                        if ((!trivial(d.text))) {
                            hidden = (hidden + 1);
                        }
                    } else {
                        _ = try ops.append(allocator, d);
                    }
                }
                for (ins.items) |n| {
                    _ = &n;
                    const nl = (n.new_no - 1);
                    var fold = sideOk((&sn), nl, n.text, unseen_old.items);
                    _ = &fold;
                    if (((fold and (!sn.noImage(nl))) and (dels.items.len > 0))) {
                        var matched = false;
                        _ = &matched;
                        for (dels.items) |d| {
                            _ = &d;
                            if (((!so.noImage((d.old_no - 1))) and codeOnly(n, (&sn), nl, d, (&so), (d.old_no - 1)))) {
                                matched = true;
                                break;
                            }
                        }
                        fold = matched;
                    }
                    if (fold) {
                        _ = try ops.append(allocator, Op{ .kind = .equal, .old_no = n.old_no, .new_no = n.new_no, .text = n.text, .affected = n.affected });
                    } else {
                        _ = try ops.append(allocator, n);
                    }
                }
            }
        }
        return Projection{ .ops = ops.items, .hidden = hidden };
}
